WITH "r0" AS ( SELECT "s".* FROM "public"."author" AS "s" WHERE true AND ( "s"."id" >= $1 ) ORDER BY "s"."id" DESC NULLS FIRST LIMIT 3 OFFSET 1 ) SELECT row_to_json((SELECT "%" FROM (SELECT row_to_json((SELECT "%" FROM (SELECT count( "t0" .*) AS "count" , row_to_json((SELECT "%" FROM (SELECT sum( "t0"."id" ) AS "id" ) AS "%")) AS "sum" , row_to_json((SELECT "%" FROM (SELECT avg( "t0"."id" ) AS "id" ) AS "%")) AS "avg" , row_to_json((SELECT "%" FROM (SELECT min( "t0"."id" ) AS "id" ) AS "%")) AS "min" , row_to_json((SELECT "%" FROM (SELECT max( "t0"."id" ) AS "id" ) AS "%")) AS "max" ) AS "%")) AS "aggregate" , coalesce(json_agg( "c1"."j" ORDER BY "t0"."id" DESC NULLS FIRST ), '[]') AS "nodes" ) AS "%")) FROM "r0" AS "t0" LEFT JOIN LATERAL (SELECT row_to_json((SELECT "%" FROM (SELECT "t0"."id" AS "id" , "t0"."name" AS "name" , coalesce( "c2"."j" , '[]'::json ) AS "articles" ) AS "%")) AS "j" FROM (SELECT true) AS "_" LEFT JOIN (WITH "r1" AS ( SELECT "s".* FROM "public"."article" AS "s" WHERE ( "s"."author_id" ) IN (SELECT "id" FROM "r0" ) AND ( ( true ) ) ) SELECT "t1"."author_id" AS "k0" , coalesce(json_agg( row_to_json((SELECT "%" FROM (SELECT "t1"."id" AS "id" ) AS "%")) ), '[]') AS "j" FROM "r1" AS "t1" GROUP BY "t1"."author_id" ) AS "c2" ON true AND "c2"."k0" = "t0"."id" ) AS "c1" ON true
